grant usage on schema public to authenticated;

-- 0001_concierge.sql
create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  currency text not null default 'EUR' check (currency in ('USD','EUR','AMD','RUB','GBP','CHF','AED','JPY','CNY','TRY')),
  created_at timestamptz not null default now()
);
create table public.trips (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
  city text not null default 'rome' check (city='rome'), title text not null check (char_length(title) between 1 and 120),
  plan jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index trips_owner on public.trips(user_id);
create table public.trip_items (
  id uuid primary key, trip_id uuid not null references public.trips(id) on delete cascade,
  place_id text not null, day integer not null check (day between 1 and 21), position integer not null check (position between 0 and 99)
);
create index trip_items_parent on public.trip_items(trip_id);
create table public.saved_places (
  user_id uuid not null references auth.users(id) on delete cascade, place_id text not null,
  created_at timestamptz not null default now(), primary key(user_id,place_id)
);
create table public.concierge_threads (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
  title text not null default 'Rome concierge', created_at timestamptz not null default now()
);
create index concierge_thread_owner on public.concierge_threads(user_id);
create table public.concierge_messages (
  id uuid primary key default gen_random_uuid(), thread_id uuid not null references public.concierge_threads(id) on delete cascade,
  role text not null check(role in ('user','assistant')), content text not null check(char_length(content)<=16000),
  created_at timestamptz not null default now()
);
create index concierge_message_parent on public.concierge_messages(thread_id);
create table public.concierge_usage (
  user_id uuid not null references auth.users(id) on delete cascade, bucket timestamptz not null,
  used integer not null default 1, primary key(user_id,bucket)
);
alter table public.profiles enable row level security;
alter table public.trips enable row level security;
alter table public.trip_items enable row level security;
alter table public.saved_places enable row level security;
alter table public.concierge_threads enable row level security;
alter table public.concierge_messages enable row level security;
alter table public.concierge_usage enable row level security;
create policy profiles_owner on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy trips_owner on public.trips for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy saved_owner on public.saved_places for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy threads_owner on public.concierge_threads for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy items_owner on public.trip_items for all to authenticated
  using(exists(select 1 from public.trips t where t.id=trip_id and t.user_id=(select auth.uid())))
  with check(exists(select 1 from public.trips t where t.id=trip_id and t.user_id=(select auth.uid())));
create policy messages_owner on public.concierge_messages for all to authenticated
  using(exists(select 1 from public.concierge_threads t where t.id=thread_id and t.user_id=(select auth.uid())))
  with check(exists(select 1 from public.concierge_threads t where t.id=thread_id and t.user_id=(select auth.uid())));
create policy usage_read on public.concierge_usage for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.profiles,public.trips,public.trip_items,public.saved_places,public.concierge_threads,public.concierge_messages,public.concierge_usage from anon;
grant select,insert,update,delete on public.profiles,public.trips,public.trip_items,public.saved_places,public.concierge_threads,public.concierge_messages to authenticated;
grant select on public.concierge_usage to authenticated;

create or replace function public.save_trip(p_id uuid, p_plan jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
declare result_id uuid; entry jsonb; ordinal integer:=0;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if jsonb_typeof(p_plan->'items') is distinct from 'array' or jsonb_array_length(p_plan->'items')>100 then raise exception 'Invalid plan'; end if;
  if p_id is null then
    insert into public.trips(user_id,title,plan) values(auth.uid(),p_plan->>'title',p_plan) returning id into result_id;
  else
    update public.trips set title=p_plan->>'title',plan=p_plan,updated_at=now() where id=p_id and user_id=auth.uid() returning id into result_id;
    if result_id is null then raise exception 'Trip unavailable'; end if;
    delete from public.trip_items where trip_id=result_id;
  end if;
  for entry in select value from jsonb_array_elements(p_plan->'items') loop
    insert into public.trip_items(id,trip_id,place_id,day,position) values((entry->>'id')::uuid,result_id,entry->>'placeId',(entry->>'day')::integer,ordinal);
    ordinal:=ordinal+1;
  end loop;
  return result_id;
end $$;
revoke all on function public.save_trip(uuid,jsonb) from public,anon;
grant execute on function public.save_trip(uuid,jsonb) to authenticated;

-- Only this atomic function can increment usage. No service-role key is needed.
create or replace function public.consume_concierge_quota() returns boolean language plpgsql security definer set search_path='' as $$
declare current_used integer;
begin
  if auth.uid() is null then return false; end if;
  insert into public.concierge_usage(user_id,bucket,used) values(auth.uid(),date_trunc('hour',now()),1)
    on conflict(user_id,bucket) do update set used=public.concierge_usage.used+1 returning used into current_used;
  return current_used<=10;
end $$;
revoke all on function public.consume_concierge_quota() from public,anon;
grant execute on function public.consume_concierge_quota() to authenticated;

-- 0002_custom_requests.sql
create table public.custom_plan_requests (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
  city text not null check (city='rome'), brief text not null check(char_length(brief) between 20 and 2000),
  status text not null default 'requested' check(status in ('requested','quoted','closed')),
  created_at timestamptz not null default now()
);
create index custom_request_owner on public.custom_plan_requests(user_id);
alter table public.custom_plan_requests enable row level security;
create policy request_read on public.custom_plan_requests for select to authenticated using(user_id=(select auth.uid()));
create policy request_insert on public.custom_plan_requests for insert to authenticated with check(user_id=(select auth.uid()) and status='requested');
revoke all on public.custom_plan_requests from anon;
grant select,insert on public.custom_plan_requests to authenticated;
-- Bound storage even if a signed-in client bypasses the application form.
alter table public.trips add constraint trip_plan_size check(octet_length(plan::text)<=48000);

-- 0003_revoke_table_management.sql
-- Supabase projects can retain default table-management grants even when
-- SELECT/INSERT/UPDATE/DELETE were explicitly configured. RLS does not guard TRUNCATE.
-- Revoke permissions only; no rows or tables are deleted.
revoke truncate, references, trigger on table
  public.profiles,
  public.trips,
  public.trip_items,
  public.saved_places,
  public.concierge_threads,
  public.concierge_messages,
  public.concierge_usage,
  public.custom_plan_requests
from authenticated, anon, public;

-- Fail atomically if another inherited grant still allows these operations.
do $$
begin
  if exists (
    select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relname in
      ('profiles','trips','trip_items','saved_places','concierge_threads',
       'concierge_messages','concierge_usage','custom_plan_requests')
      and (has_table_privilege('authenticated',c.oid,'TRUNCATE,REFERENCES,TRIGGER')
        or has_table_privilege('anon',c.oid,'TRUNCATE,REFERENCES,TRIGGER'))
  ) then
    raise exception 'Inherited table-management permissions remain; inspect role grants.';
  end if;
end $$;

-- 0004_destination_context.sql
-- Additive destination identity for existing Rome data. Apply after 0001–0003.
-- No existing application data or ownership policies are removed.
create table public.travel_destinations (
  id text primary key check (id ~ '^[a-z][a-z0-9-]*/[a-z][a-z0-9-]*$'),
  name text not null,
  country_slug text not null,
  city_slug text not null,
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  catalog_ready boolean not null default false,
  unique (id,city_slug)
);
insert into public.travel_destinations(id,name,country_slug,city_slug,currency,catalog_ready)
values ('italy/rome','Rome','italy','rome','EUR',true);
alter table public.travel_destinations enable row level security;
revoke all on public.travel_destinations from anon,authenticated;
grant select on public.travel_destinations to anon,authenticated;
create policy destination_directory_read on public.travel_destinations for select to anon,authenticated using(true);

alter table public.trips add column destination_id text not null default 'italy/rome' references public.travel_destinations(id);
alter table public.saved_places add column destination_id text not null default 'italy/rome' references public.travel_destinations(id);
alter table public.concierge_threads add column destination_id text not null default 'italy/rome' references public.travel_destinations(id);
alter table public.custom_plan_requests add column destination_id text not null default 'italy/rome' references public.travel_destinations(id);

update public.trips set plan=jsonb_set(plan,'{destinationId}','"italy/rome"'::jsonb) where not (plan ? 'destinationId');
alter table public.trips add constraint trips_plan_destination_matches check (plan->>'destinationId' is not null and plan->>'destinationId'=destination_id);
-- Replace the Rome-only checks with a link to the supported destination directory.
alter table public.trips drop constraint trips_city_check;
alter table public.custom_plan_requests drop constraint custom_plan_requests_city_check;
alter table public.trips add constraint trips_city_destination foreign key(destination_id,city) references public.travel_destinations(id,city_slug);
alter table public.custom_plan_requests add constraint custom_requests_city_destination foreign key(destination_id,city) references public.travel_destinations(id,city_slug);

-- A saved journey or conversation keeps its destination. A new destination starts a new one.
create function public.keep_destination_context() returns trigger language plpgsql security invoker set search_path='' as $$
begin
  if new.destination_id is distinct from old.destination_id then raise exception 'Start a new journey or conversation to change destination'; end if;
  return new;
end $$;
revoke all on function public.keep_destination_context() from public,anon,authenticated;
create trigger trip_destination_stays before update on public.trips for each row execute function public.keep_destination_context();
create trigger thread_destination_stays before update on public.concierge_threads for each row execute function public.keep_destination_context();

create or replace function public.save_trip(p_id uuid, p_plan jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
declare result_id uuid; entry jsonb; ordinal integer:=0; selected_id text; selected_city text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  selected_id:=coalesce(p_plan->>'destinationId','italy/rome');
  select city_slug into selected_city from public.travel_destinations where id=selected_id and catalog_ready;
  if selected_city is null then raise exception 'Destination planning is unavailable'; end if;
  if jsonb_typeof(p_plan->'items') is distinct from 'array' or jsonb_array_length(p_plan->'items')>100 then raise exception 'Invalid plan'; end if;
  p_plan:=jsonb_set(p_plan,'{destinationId}',to_jsonb(selected_id));
  if p_id is null then
    insert into public.trips(user_id,city,destination_id,title,plan)
      values(auth.uid(),selected_city,selected_id,p_plan->>'title',p_plan) returning id into result_id;
  else
    update public.trips set city=selected_city,destination_id=selected_id,title=p_plan->>'title',plan=p_plan,updated_at=now()
      where id=p_id and user_id=auth.uid() returning id into result_id;
    if result_id is null then raise exception 'Trip unavailable'; end if;
    delete from public.trip_items where trip_id=result_id;
  end if;
  for entry in select value from jsonb_array_elements(p_plan->'items') loop
    insert into public.trip_items(id,trip_id,place_id,day,position)
      values((entry->>'id')::uuid,result_id,entry->>'placeId',(entry->>'day')::integer,ordinal);
    ordinal:=ordinal+1;
  end loop;
  return result_id;
end $$;
revoke all on function public.save_trip(uuid,jsonb) from public,anon;
grant execute on function public.save_trip(uuid,jsonb) to authenticated;
commit;
